#!/usr/bin/env python3
"""Score a release against a corpus generated by make_heldout_corpus.py.

Deliberately re-implements the check the way the organizer's own check_dev.py
does it -- a normalized substring search for every entity surface in the
published file (or in its published PATH, for the filename channel) -- rather
than asking NijSetu's own leak scanner, which would be the transform grading
itself. Breakdowns are per type, per language and per channel, because an
aggregate leak rate hides exactly the failure that matters (one channel at
100%).

    python scripts/score_heldout.py <corpus_dir> <output_dir>
"""

from __future__ import annotations

import json
import sys
import unicodedata
from collections import Counter, defaultdict
from pathlib import Path


def norm(text: str) -> str:
    return unicodedata.normalize("NFC", text or "")


def main() -> int:
    if len(sys.argv) != 3:
        print(__doc__)
        return 2
    corpus, out = Path(sys.argv[1]), Path(sys.argv[2])
    truth = json.loads((corpus / "truth.json").read_text(encoding="utf-8"))
    report = json.loads((out / "report.json").read_text(encoding="utf-8"))
    san = out / "sanitized"

    # The spec lets a submission rename an output file; report.json declares the
    # mapping, so follow it rather than assuming the input path.
    by_input: dict[str, str | None] = {}
    inputs = sorted(truth["files"])
    declared = [(e.get("input_sha256"), e.get("output"), e.get("status")) for e in report.get("files") or []]
    import hashlib
    sha_to_rel = {}
    for rel in inputs:
        sha_to_rel[hashlib.sha256((corpus / "input" / rel).read_bytes()).hexdigest()] = rel
    for sha, output, _status in declared:
        rel = sha_to_rel.get(sha)
        if rel is not None:
            by_input[rel] = str(output).replace("sanitized/", "", 1) if output else None

    leaks: Counter = Counter()
    totals: Counter = Counter()
    by_script: dict[str, Counter] = defaultdict(Counter)
    by_channel: dict[str, Counter] = defaultdict(Counter)
    examples: list[tuple[str, str, str, str]] = []
    exported = quarantined = 0
    preserved_ok = preserved_all = 0

    for rel, f in truth["files"].items():
        out_rel = by_input.get(rel, rel)
        path = (san / out_rel) if out_rel else None
        exists = bool(path and path.is_file())
        exported += exists
        quarantined += not exists
        text = norm(path.read_text(encoding="utf-8", errors="replace")) if exists else ""
        fname = norm(out_rel or "")
        for _loc, unit in f["units"].items():
            for e in unit["entities"]:
                kind, script, channel = e["type"], e["script"], e["channel"]
                totals[kind] += 1
                by_script[script]["total"] += 1
                by_channel[channel]["total"] += 1
                surface = norm(e["surface"])
                haystack = fname if channel == "filename" else text
                hit = bool(surface) and (exists or channel == "filename") and surface in haystack
                if hit:
                    leaks[kind] += 1
                    by_script[script]["leak"] += 1
                    by_channel[channel]["leak"] += 1
                    if len(examples) < 20:
                        examples.append((kind, channel, rel, e["surface"]))
            if exists:
                for pv in unit.get("preserve") or []:
                    preserved_all += 1
                    preserved_ok += norm(pv["text"]) in text

    total_entities = sum(totals.values())
    total_leaks = sum(leaks.values())

    def pct(n: int, d: int) -> str:
        return "  n/a" if not d else f"{100.0 * n / d:5.1f}%"

    print("=" * 68)
    print(" HELD-OUT GENERALIZATION CHECK (independent corpus, new surface forms)")
    print("=" * 68)
    print(f"\nfiles: {len(truth['files'])}  exported: {exported}  quarantined: {quarantined}")
    print(f"\nLEAKED: {total_leaks} of {total_entities} entities ({pct(total_leaks, total_entities).strip()})")
    for kind in sorted(totals, key=lambda k: (-leaks[k], k)):
        print(f"   {kind:<16} {leaks[kind]:>3} / {totals[kind]:<4} {pct(leaks[kind], totals[kind])}")
    print("\n   by language: " + ", ".join(
        f"{s} {pct(c['leak'], c['total']).strip()}" for s, c in sorted(by_script.items())))
    print("   by channel:  " + ", ".join(
        f"{c} {v['leak']}/{v['total']}" for c, v in sorted(by_channel.items())))
    print(f"\nCLINICAL VALUES KEPT: {preserved_ok} / {preserved_all} "
          f"({pct(preserved_ok, preserved_all).strip()})")
    if examples:
        print("\nleaks (type, channel, input file, surface):")
        for kind, channel, rel, surface in examples:
            print(f"   {kind:<14} {channel:<9} {rel:<46} {surface!r}")
    return 1 if total_leaks else 0


if __name__ == "__main__":
    raise SystemExit(main())
